export type ApiKeyStatus = "active" | "revoked" | "expired" | "suspended";

/** Shape the Developers page receives — never includes the hash. */
export type SerializedApiKey = {
  id: string;
  name: string;
  prefix: string;
  scopes: ApiScope[];
  status: ApiKeyStatus;
  createdAt: string;
  lastUsedAt: string | null;
