  usage: { requestsToday: number; requestsThisMonth: number; pipelineJobsToday: number };
};

export type DevelopersPayload = {
  plan: "free" | "pro";
  limits: {
    requestsPerMinute: number;
    pipelineJobsPerDay: number;
    maxActiveKeys: number;
  };
  usage: { requestsToday: number; requestsThisMonth: number; pipelineJobsToday: number };
  keys: SerializedApiKey[];
