/**
 * Single source of truth for "is this user Pro?" outside the signed-in web
 * flow (public API keys, Developers page). Computes the plan from
 * `User.plan` + `Subscription.currentPeriodEnd` with the same grace rule as the
 * app (`isProSubscriberPlan`) — it never relies on the lazy
 * `reconcileExpiredProSubscription`, which only runs on web requests.
 *
 * Cached per user for `API_PLAN_CACHE_TTL_MS` (default 60s) in an in-memory LRU.
 * The cache is per server instance: `invalidateUserPlan` clears this instance
 * immediately; other instances pick the change up within the TTL.
 */

import { prisma } from "@/db";
import { isProSubscriberPlan } from "@/services/billing/userPlanAccess";

export type PlanTier = "free" | "pro";

const DEFAULT_TTL_MS = 60_000;
const MAX_ENTRIES = 5_000;

function cacheTtlMs(): number {
  const raw = Number.parseInt(process.env.API_PLAN_CACHE_TTL_MS ?? "", 10);
  return Number.isFinite(raw) && raw >= 0 ? raw : DEFAULT_TTL_MS;
}

type CacheEntry = { plan: PlanTier; expiresAt: number };

// Map keeps insertion order: re-inserting on read makes it an LRU.
const cache = new Map<string, CacheEntry>();

function readCache(userId: string): PlanTier | null {
  const entry = cache.get(userId);
  if (!entry) {
    return null;
  }
  if (entry.expiresAt <= Date.now()) {
    cache.delete(userId);
    return null;
  }
  cache.delete(userId);
  cache.set(userId, entry);
  return entry.plan;
}

function writeCache(userId: string, plan: PlanTier): void {
  const ttl = cacheTtlMs();
  if (ttl === 0) {
    return;
  }
  cache.delete(userId);
  cache.set(userId, { plan, expiresAt: Date.now() + ttl });
  while (cache.size > MAX_ENTRIES) {
    const oldest = cache.keys().next().value;
    if (oldest === undefined) {
      break;
    }
    cache.delete(oldest);
  }
}

/** Effective plan for a user id (`User.id`, not the Clerk id). Unknown users are free. */
export async function getUserPlan(userId: string): Promise<PlanTier> {
  const cached = readCache(userId);
  if (cached) {
    return cached;
  }

  const user = await prisma.user.findUnique({
    where: { id: userId },
    select: {
      plan: true,
      subscription: { select: { currentPeriodEnd: true } },
    },
  });

  const plan: PlanTier =
    user &&
    isProSubscriberPlan(user.plan, user.subscription?.currentPeriodEnd ?? null)
      ? "pro"
      : "free";

  writeCache(userId, plan);
  return plan;
}

/** Call after any plan change (payment confirmed, expiry reconciled). */
export function invalidateUserPlan(userId: string): void {
  cache.delete(userId);
}
import type { ApiKey } from "@/db/generated/client";
import { prisma } from "@/db";

export type ApiKeyWrite = {
  userId: string;
  name: string;
  prefix: string;
  hashedKey: string;
  scopes: string[];
  expiresAt: Date | null;
};

/** Keys that still count toward the per-user cap: not revoked, not expired. */
function activeKeyWhere(userId: string, now: Date) {
  return {
    userId,
    revokedAt: null,
    OR: [{ expiresAt: null }, { expiresAt: { gt: now } }],
  };
}

export function listApiKeysByUserId(userId: string): Promise<ApiKey[]> {
  return prisma.apiKey.findMany({
    where: { userId },
    orderBy: [{ revokedAt: { sort: "asc", nulls: "first" } }, { createdAt: "desc" }],
  });
}

/**
 * Insert a key unless the user already has `maxActiveKeys` active ones.
 * Serializable so two concurrent creates can't both pass the count.
 */
export async function createApiKeyWithinLimit(
  data: ApiKeyWrite,
  maxActiveKeys: number,
): Promise<ApiKey | null> {
  return prisma.$transaction(
    async (tx) => {
      const active = await tx.apiKey.count({
        where: activeKeyWhere(data.userId, new Date()),
      });
      if (active >= maxActiveKeys) {
        return null;
      }
      return tx.apiKey.create({ data });
    },
    { isolationLevel: "Serializable" },
  );
}

/** Revoke an owned key. Returns false when it doesn't exist or isn't the user's. */
export async function revokeApiKeyForUser(
  userId: string,
  apiKeyId: string,
): Promise<boolean> {
  const result = await prisma.apiKey.updateMany({
    where: { id: apiKeyId, userId, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (result.count > 0) {
    return true;
  }
  // Already revoked still counts as success for its owner.
  const owned = await prisma.apiKey.count({ where: { id: apiKeyId, userId } });
  return owned > 0;
}

export function findApiKeyByHash(hashedKey: string): Promise<ApiKey | null> {
  return prisma.apiKey.findUnique({ where: { hashedKey } });
}

export async function touchApiKeyLastUsed(apiKeyId: string, at: Date) {
  await prisma.apiKey.update({
    where: { id: apiKeyId },
    data: { lastUsedAt: at },
  });
}

export type ApiKeyUsageCounts = {
  requestsToday: number;
  requestsThisMonth: number;
  pipelineJobsToday: number;
};

/** Per-key request counts since `dayStart` / `monthStart` (UTC). */
export async function countApiUsageByKey(input: {
  userId: string;
  dayStart: Date;
  monthStart: Date;
}): Promise<Map<string, ApiKeyUsageCounts>> {
  const [month, day, pipeline] = await Promise.all([
    prisma.apiRequestLog.groupBy({
      by: ["apiKeyId"],
      where: { userId: input.userId, createdAt: { gte: input.monthStart } },
      _count: { _all: true },
    }),
    prisma.apiRequestLog.groupBy({
      by: ["apiKeyId"],
      where: { userId: input.userId, createdAt: { gte: input.dayStart } },
      _count: { _all: true },
    }),
    // Accepted pipeline jobs answer 202.
    prisma.apiRequestLog.groupBy({
      by: ["apiKeyId"],
      where: {
        userId: input.userId,
        createdAt: { gte: input.dayStart },
        costClass: "pipeline",
        status: 202,
      },
      _count: { _all: true },
    }),
  ]);

  const usage = new Map<string, ApiKeyUsageCounts>();
  const entry = (apiKeyId: string) => {
    let row = usage.get(apiKeyId);
    if (!row) {
      row = { requestsToday: 0, requestsThisMonth: 0, pipelineJobsToday: 0 };
      usage.set(apiKeyId, row);
    }
    return row;
  };
  for (const row of month) entry(row.apiKeyId).requestsThisMonth = row._count._all;
  for (const row of day) entry(row.apiKeyId).requestsToday = row._count._all;
  for (const row of pipeline) entry(row.apiKeyId).pipelineJobsToday = row._count._all;
  return usage;
}
/// Public REST API (v1) keys. Only the SHA-256 of the full key is stored.
model ApiKey {
  id String @id @default(uuid()) @db.Uuid

  userId String @map("user_id")

  /// User-given label, e.g. "Trading bot".
  name String

  /// First 12 chars of the key (`ds_live_xxxx`), shown in the UI.
  prefix String @unique

  /// Hex SHA-256 of the full key; the full key is never stored.
  hashedKey String @unique @map("hashed_key")

  scopes String[] @default([])

  lastUsedAt DateTime? @map("last_used_at") @db.Timestamptz(6)
  expiresAt  DateTime? @map("expires_at") @db.Timestamptz(6)
  revokedAt  DateTime? @map("revoked_at") @db.Timestamptz(6)
  createdAt  DateTime  @default(now()) @map("created_at") @db.Timestamptz(6)

  user        User            @relation(fields: [userId], references: [id], onDelete: Cascade)
  requestLogs ApiRequestLog[]

  @@index([userId, revokedAt])
  @@map("api_keys")
}

/// One row per v1 request: usage page, quotas and debugging.
model ApiRequestLog {
  id String @id @default(uuid()) @db.Uuid

  apiKeyId String @map("api_key_id") @db.Uuid
  userId   String @map("user_id")

  method     String
  path       String
  status     Int
  durationMs Int    @map("duration_ms")
  /// `read` | `search` | `pipeline`
  costClass  String @map("cost_class")
  requestId  String @map("request_id")

  createdAt DateTime @default(now()) @map("created_at") @db.Timestamptz(6)

  apiKey ApiKey @relation(fields: [apiKeyId], references: [id], onDelete: Cascade)
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([apiKeyId, createdAt])
  @@index([userId, createdAt])
  @@map("api_request_logs")
}

import { NextResponse } from "next/server";
import { z } from "zod";
import { requireAuthenticatedUser } from "@/lib/auth";
import {
  listRecentNewsRequests,
  requestNews,
  requestNewsBodySchema,
} from "@/services/news/apiService";

export async function GET() {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const newsRequests = await listRecentNewsRequests(user.id);
  return NextResponse.json({ newsRequests });
}

export async function POST(request: Request) {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const parsed = requestNewsBodySchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Validation failed", details: z.treeifyError(parsed.error) },
      { status: 400 },
    );
  }

  try {
    const result = await requestNews(user.id, parsed.data, user.clerkId);
    return NextResponse.json(result, { status: result.created ? 201 : 200 });
  } catch (error) {
    const message = error instanceof Error ? error.message : "Request failed";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { requireProApiUser } from "@/lib/requireProApiUser";
import {
  listUserStockResearchesPage,
  startStockResearch,
  startStockResearchBodySchema,
  StockResearchInputError,
} from "@/services/stockResearch/apiService";
import { researchAssetTypeSchema } from "@/repositories/stockResearch";
import {
  STOCK_RESEARCHES_MAX_LIMIT,
  STOCK_RESEARCHES_PAGE_SIZE,
} from "@/services/stockResearch/stockResearchTypes";

const listQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce
    .number()
    .int()
    .min(1)
    .max(STOCK_RESEARCHES_MAX_LIMIT)
    .default(STOCK_RESEARCHES_PAGE_SIZE),
  assetType: researchAssetTypeSchema.optional(),
});

/** Recent stock researches, newest first. `?page=&limit=` (limit ≤ 10). */
export async function GET(request: Request) {
  const { user, response } = await requireProApiUser();
  if (!user) {
    return response;
  }

  const { searchParams } = new URL(request.url);
  const parsed = listQuerySchema.safeParse({
    page: searchParams.get("page") ?? undefined,
    limit: searchParams.get("limit") ?? undefined,
    assetType: searchParams.get("assetType") ?? undefined,
  });
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid query parameters" },
      { status: 400 },
    );
  }

  const result = await listUserStockResearchesPage({
    userId: user.id,
    page: parsed.data.page,
    limit: parsed.data.limit,
    assetType: parsed.data.assetType,
  });
  return NextResponse.json(result);
}

/** Create a PENDING stock research and start the pipeline. */
export async function POST(request: Request) {
  const { user, response } = await requireProApiUser();
  if (!user) {
    return response;
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const parsed = startStockResearchBodySchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      {
        error: parsed.error.issues[0]?.message ?? "Validation failed",
        details: z.treeifyError(parsed.error),
      },
      { status: 400 },
    );
  }

  try {
    const stockResearch = await startStockResearch(user, parsed.data);
    return NextResponse.json({ stockResearch }, { status: 201 });
  } catch (error) {
    if (error instanceof StockResearchInputError) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    const message =
      error instanceof Error ? error.message : "Failed to start research";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}
