const RERUN_INITIAL_LOG = "Refreshing your briefing.";

/** Start incremental rerun: flag request, reset progress logs, enqueue Inngest. */
export async function startNewsRequestRerun(
  userId: string,
  newsRequestId: string,
  endUserId: string,
) {
  const newsRequest = await getNewsRequestByIdForUser(newsRequestId, userId);
  if (!newsRequest) {
    return null;
  }
  if (newsRequest.status !== "success") {
    return { error: "not_ready" as const };
  }
  if (newsRequest.isRerunning) {
    return { error: "already_rerunning" as const };
  }

  await patchNewsRequest(newsRequest.id, {
    isRerunning: true,
    loadingLogs: [RERUN_INITIAL_LOG],
  });

  await runWorkflow(
    WORKFLOWS.newsRerun,
    {
      endUserId,
      userId,
      source: "web",
      input: { newsRequestId: newsRequest.id },
    },
    (trace) => enqueueNewsRerunPipeline(newsRequest.id, trace),
  );

  const updated = await getNewsRequestByIdForUser(newsRequestId, userId);
  if (!updated) {
    return null;
  }

  const stories = await loadStoriesIfReady(updated.id, updated.status, userId);
  const createdStoryCount =
    (await countStoriesByNewsRequestIds([updated.id])).get(updated.id) ?? 0;

  return {
    newsRequest: serializeNewsRequest(updated, createdStoryCount),
    stories,
  };
}

/** Re-run pipeline for a failed request owned by the user. */
export async function retryFailedNewsRequest(
  userId: string,
  newsRequestId: string,
  endUserId: string,
) {
  const newsRequest = await getNewsRequestByIdForUser(newsRequestId, userId);
  if (!newsRequest || newsRequest.status !== "failed") {
    return null;
  }

  const config = newsGenerationConfigFromNewsRequest(newsRequest);

  await patchNewsRequest(newsRequest.id, {
    status: "pending",
    error: null,
    completedAt: null,
  });

  await appendNewsRequestLoadingLog(newsRequest.id, "Manual retry started.");

  await triggerNewsPipeline({
    userId,
    endUserId,
    newsRequestId: newsRequest.id,
    config,
  });

  const updated = await getNewsRequestByIdForUser(newsRequestId, userId);
  if (!updated) {
    return null;
  }

  return {
    newsRequest: serializeNewsRequest(updated),
    stories: [] as ReturnType<typeof serializeStory>[],
  };
}

